import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";

const MODELS = {
  figure: "models/figure.glb",
  web: "models/web.glb",
  automation: "models/automation.glb",
  saas: "models/saas.glb",
  laptop: "models/laptop.glb",
  camera: "models/camera.glb",
  sketchbook: "models/sketchbook.glb",
};

// Ink shader textures, generated by tools/make_textures.py
const TEXTURES = {
  hatch: "textures/hatch.png",
  noise: "textures/noise.png",
};

export const assets = { models: {}, textures: {} };

export async function loadAssets(onProgress = () => {}) {
  const total = Object.keys(MODELS).length + Object.keys(TEXTURES).length + 1;
  let done = 0;
  const tick = () => onProgress(++done / total);

  const gltf = new GLTFLoader();
  const tex = new THREE.TextureLoader();
  const modelJobs = Object.entries(MODELS).map(([k, url]) =>
    gltf.loadAsync(url).then((g) => {
      assets.models[k] = g.scene;
      tick();
    })
  );
  const texJobs = Object.entries(TEXTURES).map(([k, url]) =>
    tex.loadAsync(url).then((t) => {
      t.wrapS = t.wrapT = THREE.RepeatWrapping;
      assets.textures[k] = t;
      tick();
    })
  );
  // canvas-drawn signs and screens need the fonts first
  const fontJob = document.fonts.ready
    .then(() => Promise.all([document.fonts.load("64px Limelight"), document.fonts.load("700 32px Archivo")]))
    .then(tick);
  await Promise.all([...modelJobs, ...texJobs, fontJob]);
  return assets;
}

/** Clone a loaded model (meshes share geometry; materials are replaced per use). */
export function cloneModel(key) {
  return assets.models[key].clone(true);
}

/** Draw text/UI onto a canvas texture. draw(ctx, w, h) does the painting. */
export function canvasTexture(w, h, draw) {
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  const g = c.getContext("2d");
  draw(g, w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}
